param([string]$ProjectPath='C:\Projects\gympro-api',[string]$BackupRoot='C:\Projects\gympro-backups')
$ErrorActionPreference='Stop'
$code=0
$oldPassword=[Environment]::GetEnvironmentVariable('PGPASSWORD','Process')
$created=$false
try {
 $bin='C:\Program Files\PostgreSQL\18\bin'
 foreach($exe in @('psql.exe','createdb.exe','dropdb.exe')){if(-not(Test-Path (Join-Path $bin $exe))){throw "Missing PostgreSQL executable: $exe"}}
 if(-not(Test-Path (Join-Path $ProjectPath 'package.json'))){throw 'Gym Pro project not found.'}
 $suffix=(Get-Date -Format 'yyyyMMddHHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,6)
 $target='gympro_bootstrap_'+$suffix.Replace('-','_')
 if($target -notmatch '^gympro_bootstrap_[0-9]{14}_[a-f0-9]{6}$'){throw 'Unsafe target database name.'}
 $report=Join-Path $BackupRoot ('completion-batch1c-'+$suffix)
 $payload=Join-Path $report 'baseline'
 New-Item -ItemType Directory -Path $report -Force | Out-Null
 $zip=Join-Path $report 'baseline.zip'
 [IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String(''))
 Expand-Archive -LiteralPath $zip -DestinationPath $payload
 $manifest=Get-Content (Join-Path $payload 'baseline-manifest.json') -Raw | ConvertFrom-Json
 if((Get-FileHash (Join-Path $payload 'schema.sql') -Algorithm SHA256).Hash.ToLowerInvariant() -cne $manifest.sha256){throw 'Recovered schema checksum mismatch.'}
 $destination=Join-Path $ProjectPath 'sql\baseline-20261016'
 if(Test-Path $destination){throw 'Recovered baseline folder already exists. Stop to inspect existing installation.'}
 $runnerTarget=Join-Path $ProjectPath 'scripts\completion-batch1c-rehearsal.ps1'
 if(Test-Path $runnerTarget){throw 'Rehearsal runner already exists. Stop to inspect the previous run.'}
 $secure=Read-Host 'Local PostgreSQL postgres password' -AsSecureString
 $ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
 try {$env:PGPASSWORD=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)} finally {[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr);$secure.Dispose()}
 Write-Host "CHECK: Create empty rehearsal database $target" -ForegroundColor Cyan
 & (Join-Path $bin 'createdb.exe') -w -h 127.0.0.1 -p 5432 -U postgres --template=template0 $target
 if($LASTEXITCODE -ne 0){throw 'Temporary database creation failed.'}
 $created=$true
 Write-Host 'CHECK: Reconstruct schema using existing cluster roles' -ForegroundColor Cyan
 $restoreArgs=@('-X','-w','-h','127.0.0.1','-p','5432','-U','postgres','-d',$target,'--single-transaction','-v','ON_ERROR_STOP=1','-f',('"'+(Join-Path $payload 'schema.sql')+'"'))
 $restore=Start-Process -FilePath (Join-Path $bin 'psql.exe') -ArgumentList $restoreArgs -NoNewWindow -Wait -PassThru -RedirectStandardOutput (Join-Path $report 'restore.log') -RedirectStandardError (Join-Path $report 'restore-errors.log')
 if($restore.ExitCode -ne 0){throw 'Schema reconstruction failed. Retain the temporary database and restore.log for diagnosis.'}
 Write-Host 'CHECK: Empty schema, owners, RLS, runtime privileges and session rejection' -ForegroundColor Cyan
 $verifyArgs=@('-X','-w','-h','127.0.0.1','-p','5432','-U','postgres','-d',$target,'-v','ON_ERROR_STOP=1','-v',"target=$target",'-f',('"'+(Join-Path $payload 'verify-empty-baseline.sql')+'"'))
 $verification=Start-Process -FilePath (Join-Path $bin 'psql.exe') -ArgumentList $verifyArgs -NoNewWindow -Wait -PassThru -RedirectStandardOutput (Join-Path $report 'verification.log') -RedirectStandardError (Join-Path $report 'verification-errors.log')
 if($verification.ExitCode -ne 0){throw 'Baseline assertions failed. Retain the temporary database and verification.log for diagnosis.'}
 # Only this successfully created, uniquely named temporary database can be removed.
 if(-not $created -or $target -notmatch '^gympro_bootstrap_[0-9]{14}_[a-f0-9]{6}$'){throw 'Temporary database removal guard failed.'}
 & (Join-Path $bin 'dropdb.exe') -w -h 127.0.0.1 -p 5432 -U postgres $target
 if($LASTEXITCODE -ne 0){throw 'Rehearsal passed but temporary database cleanup failed.'}
 $created=$false
 New-Item -ItemType Directory -Path $destination -Force | Out-Null
 foreach($name in @('schema.sql','verify-empty-baseline.sql','baseline-manifest.json','README.md')){Copy-Item -LiteralPath (Join-Path $payload $name) -Destination $destination}
 New-Item -ItemType Directory -Path (Split-Path $runnerTarget) -Force | Out-Null
 Copy-Item -LiteralPath $PSCommandPath -Destination $runnerTarget
 $summary=[ordered]@{batch='1C recovered schema rehearsal';schemaSha256=$manifest.sha256;emptyDatabaseReconstructionPassed=$true;tablesVerified=36;securityFunctionsVerified=64;forcedRlsTables=28;runtimeTablePrivilegesVerified=$true;unknownSessionReturnedNoIdentity=$true;sessionVerifierRole='gympro_auth';appDirectVerifierDenied=$true;appPaymentUnknownSessionRejected=$true;temporaryDatabaseRemoved=$true;existingClusterRolesUsed=$true;freshClusterRoleSetupVerified=$false;seedDataInstalled=$false;migrationLedgerInstalled=$false;authenticatedBusinessFlowsVerified=$false;productionReady=$false;liveDatabaseChanged=$false;kbzPayDeferred=$true;verifiedAt=(Get-Date -Format o)}
 $summary | ConvertTo-Json | Set-Content (Join-Path $report 'batch1c-summary.json') -Encoding UTF8
 $doc=Join-Path $ProjectPath 'docs\completion'
 New-Item -ItemType Directory -Path $doc -Force | Out-Null
 Copy-Item (Join-Path $report 'batch1c-summary.json') (Join-Path $doc 'batch1c-summary.json')
 Write-Host 'PASS: Recovered schema reconstructed and checked in an empty temporary database.' -ForegroundColor Green
 Write-Host 'PASS: 36 empty tables, owners/RLS/runtime table privileges, 64 function identities/owners/security modes and unknown-session rejection verified.'
 Write-Host 'PASS: Temporary database removed; working gympro_saas was not modified.'
 Write-Host 'PENDING: Fresh-cluster roles, permission seeds, provisioning, migration ledger and clean application installation.'
 Write-Host 'No UI change, production authentication change or Git commit performed. KBZPay deferred.'
 Write-Host "Reports: $report"
} catch {
 $code=1
 Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red
 if($created){Write-Host "Retained rehearsal database: $target"}
 if($report){Write-Host "Keep reports: $report"}
} finally {[Environment]::SetEnvironmentVariable('PGPASSWORD',$oldPassword,'Process')}
exit $code
